import socket, time

HOST='crypto.chal.csaw.io'; PORT=21004

def probe(payload, maxwait=6.0, host=HOST, port=PORT):
    """Send hex payload, return (classification, response_bytes, first_byte_time)."""
    s = socket.create_connection((host, port), timeout=10)
    s.settimeout(0.2)
    banner = b''
    t0 = time.time()
    while time.time() - t0 < 2.0:
        try:
            chunk = s.recv(4096)
            if not chunk: break
            banner += chunk
            if banner.endswith(b'> '): break
        except socket.timeout:
            break
    t_send = time.time()
    s.sendall(payload + b'\n')
    resp = b''
    tf = None
    while time.time() - t_send < maxwait:
        try:
            chunk = s.recv(4096)
            if not chunk:
                resp += b'[CLOSED]'; break
            if tf is None: tf = time.time()-t_send
            resp += chunk
            if resp.endswith(b'> '): break
        except socket.timeout:
            continue
    s.close()
    if b'No connection found' in resp: return ('NOCONN', resp, tf)
    if b'Invalid communication' in resp: return ('INVALID', resp, tf)
    return ('OTHER', resp, tf)

